pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNo) public {
        blockNo = bound(blockNo, 15, type(uint256).max / 2);
        vm.assume(blockNo % 15 == 0);
        vm.roll(blockNo);
        vm.warp(blockNo + 1);
        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok && address(c).balance == 0);
    }
}
